void encl_delete ( struct encl * encl ) { struct encl_segment * heap_seg ; if ( encl -> encl_base ) { munmap ( ( void * ) encl -> encl_base , encl -> encl_size ) ; } if ( encl -> bin ) { munmap ( encl -> bin , encl -> bin_size ) ; } if ( encl -> fd ) { close ( encl -> fd ) ; } if ( encl -> segment_tbl ) { heap_seg = & encl -> segment_tbl [ encl -> nr_segments - 1 ] ; munmap ( heap_seg -> src , heap_seg -> size ) ; free ( encl -> segment_tbl ) ; } } 